#include "../host/scene_loader.hpp"
#include "../engine/native/assets/sha256.hpp"
#include <fstream>
#include <iostream>
int main(int argc,char** argv){unsigned checks=0;const auto check=[&](bool ok,const std::string& message){++checks;if(!ok)throw std::runtime_error(message);};try{
    check(argc==2,"Expected environment preview");host::SceneDocument scene;std::string error;check(host::loadScene(argv[1],scene,error),error);const auto& light=scene.scene.lighting;check(bool(light.panorama),"Native environment reference");check(light.panorama->width==16&&light.panorama->height==8,"Native panorama shape");check(light.panorama->pixels[0]==8,"Native floating radiance exceeds one");check(light.environmentIntensity==1&&light.environmentRotation==0,"Environment parameter defaults");check(light.toneMap&&light.cloudCoverage==0,"Environment display defaults");
    const auto identity=engine::gameplay::sceneIdentity(scene.scene);auto changed=scene.scene;changed.lighting.environmentFile="relocated/sky.ngenv";check(engine::gameplay::sceneIdentity(changed)==identity,"Relocation preserves environment content identity");changed.lighting.environmentIntensity=.5;check(engine::gameplay::sceneIdentity(changed)!=identity,"Intensity participates in identity");changed=scene.scene;changed.lighting.environmentRotation=180;check(engine::gameplay::sceneIdentity(changed)!=identity,"Rotation participates in identity");changed=scene.scene;changed.lighting.environmentHash=std::string(64,'0');check(engine::gameplay::sceneIdentity(changed)!=identity,"Panorama content participates in identity");
    engine::Game game;game.initialize(scene.scene);game.update({},1.f/60.f);const auto snapshot=game.snapshot();game.update({},1.f/60.f);game.restore(snapshot);check(game.snapshot()==snapshot,"Environment scene snapshot round trip");
    nlohmann::json source;std::ifstream(argv[1])>>source;const auto directory=std::filesystem::path(argv[1]).parent_path(),invalid=directory/"invalid-environment.scene.json";
    const auto reject=[&](const nlohmann::json& data){std::ofstream(invalid)<<data.dump();check(!host::loadScene(invalid,scene,error),"Invalid environment must be rejected");check(engine::gameplay::sceneIdentity(scene.scene)==identity,"Environment rejection is atomic");};
    for(const auto& value:{nlohmann::json(-1),nlohmann::json(10001),nlohmann::json(nullptr),nlohmann::json("1")}){auto bad=source;bad["lighting"]["environment"]["intensity"]=value;reject(bad);}
    for(const auto& value:{nlohmann::json(-3601),nlohmann::json(3601),nlohmann::json(nullptr)}){auto bad=source;bad["lighting"]["environment"]["rotation"]=value;reject(bad);}
    for(const auto* file:{"../sky.ngenv","environment//sky.ngenv","C:/sky.ngenv"}){auto bad=source;bad["lighting"]["environment"]["file"]=file;reject(bad);}
    auto bad=source;bad["lighting"]["environment"]["sha256"]=std::string(64,'0');reject(bad);
    std::ifstream input(directory/std::filesystem::u8path(light.environmentFile),std::ios::binary);const std::string original((std::istreambuf_iterator<char>(input)),{});const auto write=[&](std::string bytes){const auto file=directory/"invalid.ngenv";std::ofstream stream(file,std::ios::binary);stream.write(bytes.data(),bytes.size());stream.close();auto data=source;data["lighting"]["environment"]["file"]="invalid.ngenv";data["lighting"]["environment"]["sha256"]=engine::assets::sha256(bytes);reject(data);std::filesystem::remove(file);};
    auto corrupt=original;corrupt[140]=1;write(corrupt);write(original.substr(0,original.size()-1));corrupt=original;const float nan=std::nanf("");std::memcpy(corrupt.data()+160,&nan,4);write(corrupt);corrupt=original;const float alpha=.5;std::memcpy(corrupt.data()+172,&alpha,4);write(corrupt);corrupt=original;std::memcpy(corrupt.data()+32,&nan,4);write(corrupt);std::filesystem::remove(invalid);
    std::cout<<"{\"success\":true,\"checks\":"<<checks<<"}\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
